export type TrainingLevel = { id: 'new' | 'basic' | 'pro'; title: string; minShare: number };
export type TrainingMiss = {
  objectionId: string | null;
  reasonKey: string | null;
  errorType: string | null;
  violates: string | null;
};
export type TrainingAttempt = {
  id: string;
  mode: 'objection' | 'roleplay' | 'quiz';
  itemType: 'objection' | 'scenario' | 'quiz';
  itemIds: string[];
  contentVersion: string | null;
  startedAt: string;
  finishedAt: string;
  firstTryCorrect: number | null;
  count: number;
  quizPercent: number | null;
  total: number;
  passed: boolean;
  criteria: Record<string, number | null>;
  misses: TrainingMiss[];
  quizMisses: { questionId: string | null; topic: string | null }[];
};
export type MaterialOpen = { id: string; materialId: string; title: string; at: string };
export type WeakTopic = { kind: 'reason' | 'quiz'; key: string; count: number };
export type UserTrainingSummary = {
  sets: number;
  choiceSets: number;
  quizSets: number;
  passedSets: number;
  levelShare: number | null;
  level: { id: TrainingLevel['id']; title: string };
  quizShare: number | null;
  criteria: { id: string; title: string; avg: number | null; weak: boolean }[];
  weakCriteria: { id: string; title: string; avg: number | null; weak: boolean }[];
  weakTopics: WeakTopic[];
  weakObjections: { objectionId: string; count: number }[];
  lastAt: string | null;
  lastMaterialAt: string | null;
  lastActivityAt: string | null;
  materialsOpened: number;
  materialOpens: number;
  recentMaterials: { materialId: string; title: string; at: string }[];
};
export type CompanyTrainingSummary = {
  staffTotal: number;
  trained: number;
  avgShare: number | null;
  active7: number;
  active30: number;
  levels: { new: number; basic: number; pro: number };
  weakTopics: WeakTopic[];
  lastActivityAt: string | null;
};
export type RecentAttempt = {
  id: string;
  mode: TrainingAttempt['mode'];
  itemType: TrainingAttempt['itemType'];
  itemIds: string[];
  finishedAt: string;
  share: number | null;
  passed: boolean;
  count: number;
};

export const TRAINING_LEVELS: TrainingLevel[];
export const TRAINING_CRITERIA: { id: string; title: string }[];
export const ERROR_TYPES: string[];
export const TRAINING_MODES: string[];
export const LEVEL_WINDOW: number;
export const WEAK_WINDOW: number;
export const WEAK_CRITERION_BELOW: number;
export const MAX_ATTEMPTS_PER_USER: number;
export const MAX_MATERIAL_OPENS: number;
export const MAX_BATCH: number;
export function normalizeTrainingAttempt(raw: unknown, nowMs?: number): TrainingAttempt | null;
export function normalizeMaterialOpen(raw: unknown, nowMs?: number): MaterialOpen | null;
export function levelFor(share: number | null): { id: TrainingLevel['id']; title: string; minShare: number };
export function summarizeUserTraining(attempts: TrainingAttempt[], materials?: MaterialOpen[]): UserTrainingSummary;
export function recentAttempts(attempts: TrainingAttempt[], limit?: number): RecentAttempt[];
export function summarizeCompanyTraining(summaries: UserTrainingSummary[], nowMs?: number): CompanyTrainingSummary;
export function unionById<T extends { id: string }>(first: T[] | undefined, second: T[] | undefined, cap?: number): T[];
